insert into content.content_block (place_id,section,slot,ord,body,fact_refs,status,author,field)
select 'area:grand-massif',v.section,v.slot,v.ord,v.body,v.refs::text[],'review','loader',v.field from (values
('meta','line',0,'Grand Massif | Linked ski areas | Snow Catchers','{}','title'),
('meta','line',1,'How Flaine, Les Carroz, Morillon, Samoëns and Sixt share one lift network, which base reaches which slopes, how much snow falls at the height of the bowl and of the villages, which pass to buy, and what the area is like for boarders, families, food and evenings.','{}','description'),
('meta','line',2,'France','{}','crumbs.0.label'),
('meta','line',3,'Linked ski areas','{}','crumbs.1.label'),
('meta','line',4,'Northern Alps','{}','crumbs.2.label'),
('hero','lead',0,'The Grand Massif joins five resorts on one lift network above the Arve and Giffre valleys of Haute-Savoie, from the purpose built bowl of Flaine down to the old stone villages of Samoëns and Morillon near the valley floor. Alti-Mag counts {{f:F000644}} of piste between {{f:F000654|n}} and {{f:F000655}}, and the longest run, the Piste des Cascades, carries skiers {{f:F000678}} from the top of Flaine to Sixt-Fer-à-Cheval. Flaine and Samoëns were first linked through the Combe de Vernant in {{f:F000669}}, and the five resorts have shared one network since {{f:F000670}}.',array['F000644','F000654','F000655','F000669','F000670','F000678'],'hero.lead'),
('stats','line',0,'{{f:F000644}}',array['F000644'],'stats.0.v'),
('stats','line',1,'of piste across five linked resorts, the figure Alti-Mag and skiresort.com share','{}','stats.0.t'),
('stats','line',2,'{{f:F000654|n}} to {{f:F000655}}',array['F000654','F000655'],'stats.1.v'),
('stats','line',3,'from the valley floor at Morillon to the top of the Grandes Platières cable car above Flaine','{}','stats.1.t'),
('stats','line',4,'{{f:F000678}}',array['F000678'],'stats.2.v'),
('stats','line',5,'down the Piste des Cascades from the Grandes Platières to Sixt, with the skibus back to Samoëns','{}','stats.2.t'),
('stats','line',6,'{{f:F000533}}',array['F000533'],'stats.3.v'),
('stats','line',7,'for six days, adult, 2026/27, or {{f:F000704}} for the four villages without Flaine',array['F000704'],'stats.3.t'),
('network','heading',0,'Five resorts round one high bowl','{}','network.h2'),
('network','para',0,'Flaine sits in a limestone bowl at the southern end of the area, its lifts climbing from {{f:F000727}} to {{f:F000728}} at the top of the Grandes Platières cable car. Les Carroz lies west of it on a sunny shelf above the Arve, Morillon and Samoëns lie north in the Giffre valley, and Sixt sits furthest east at the head of the same valley. The five meet on the high ground between Flaine and the Tête des Saix, where the lifts from Les Carroz, Morillon and Samoëns top out between {{f:F000743|n}} and {{f:F000738}} above the Saix plateau.',array['F000727','F000728','F000738','F000743'],'network.paras.0'),
('network','para',1,'Each valley village has one main way up. Samoëns climbs from the edge of the village to Samoëns 1600 by the Grand Massif Express gondola, opened in {{f:F000671}}, with the Vercland gondola as a second way in further up the valley. Morillon rides its gondola to Morillon 1100 and then the Sairon chair, and Les Carroz has the Kédeuze gondola. In the map data a closed Kédeuze gondola leaves Les Carroz village with no lift route to any of the other {{f:F000806|w}} resorts, and the Morillon gondola and the Sairon chair hold the same place for Morillon, so on a windy day the bus or the car is the way round.',array['F000671','F000806'],'network.paras.1'),
('network','para',2,'Sixt is the exception. Its four short drags serve the beginner slopes at Salvagny and do not link to the rest by lift. The way in on skis is the Piste des Cascades, {{f:F000678}} from the top of Flaine through a nature reserve to the village, and the way out is the free skibus to the Grand Massif Express in Samoëns, about eight kilometres down the valley. The Cascades ends below 800 m and needs snow all the way down, and Mon séjour en montagne reports that it stayed shut through 2023/24 and opened on less than a tenth of the days the season before.',array['F000678'],'network.paras.2'),
('network','para',3,'Skiing here began in the valley villages. Les Carroz opened its first lift in {{f:F000665}} and Samoëns its first in {{f:F000666}}. Éric and Sylvie Boissonnas found the site of Flaine in {{f:F000667}} and asked the Bauhaus architect Marcel Breuer to design a resort, which opened in {{f:F000668}}. The Combe de Vernant joined Flaine to Samoëns in {{f:F000669}}, and the Grand Massif took its present shape in {{f:F000670}}. The newest big lifts are the Coulouvrier chair above Morillon, built for {{f:F000672}}, and the ten seat Vercland gondola, ready for {{f:F000673}}.',array['F000665','F000666','F000667','F000668','F000669','F000670','F000672','F000673'],'network.paras.3'),
('network','line',0,'{{m:all.samoens.flaine}} lift rides','{}','network.figs.0.v'),
('network','line',1,'from Samoëns village to Flaine, and {{m:all.flaine.samoens|w}} back','{}','network.figs.0.t'),
('network','line',2,'{{m:all.carroz.flaine}} lift rides','{}','network.figs.1.v'),
('network','line',3,'from Les Carroz to Flaine, by the Kédeuze gondola and the Tête des Saix chair','{}','network.figs.1.t'),
('network','line',4,'{{f:F000678}}',array['F000678'],'network.figs.2.v'),
('network','line',5,'down the Piste des Cascades to Sixt, with no lift back','{}','network.figs.2.t'),
('network','line',6,'{{m:all.morillon.sixt}} lift rides','{}','network.figs.3.v'),
('network','line',7,'from Morillon to Sixt, the longest trip between villages','{}','network.figs.3.t'),
('network','line',8,'{{f:F000669}}',array['F000669'],'network.figs.4.v'),
('network','line',9,'the Combe de Vernant links Samoëns and Flaine','{}','network.figs.4.t'),
('network','line',10,'{{f:F000671}}',array['F000671'],'network.figs.5.v'),
('network','line',11,'the Grand Massif Express opens above Samoëns','{}','network.figs.5.t'),
('network','heading',1,'Explore the network','{}','network.mapTitle'),
('network','caption',0,'Choose a starting point to see how many lift rides it takes to reach each other resort, then limit the runs to see what stays within reach.','{}','network.mapHelp'),
('network','caption',1,'Schematic, not to scale, with the resorts moved apart for legibility. Drawn from OpenStreetMap lift and piste data (© OpenStreetMap contributors, October 2026) with heights from the Copernicus 90 m elevation model. Lift rides are the fewest needed from the village lifts of one resort to the first lift of another. The dotted line is the free skibus between Sixt and Samoëns; the Cascades runs one way, from Flaine to Sixt.','{}','network.caption'),
('network','line',12,'Grandes Platières','{}','mapNotes.0.text'),
('network','line',13,'Tête des Saix','{}','mapNotes.1.text'),
('routes','heading',0,'Six sample days','{}','routes.h3'),
('routes','line',0,'Each trip is counted in lift rides out and back from the village lifts, with the easiest grade of run that makes it in the map data. Time on the pistes, in queues, on foot and on the bus is not included.','{}','routes.intro'),
('routes','line',1,'Samoëns','{}','routes.rows.0.from'),
('routes','line',2,'Flaine','{}','routes.rows.0.to'),
('routes','line',3,'Red home, or blue with more lifts','{}','routes.rows.0.grade'),
('routes','note',0,'Up the Grand Massif Express and the Chariande Express; home by the Grandes Platières and the Combe de Vernant, or on blue by the Grand Vans and Corbalanche chairs.','{}','routes.rows.0.note'),
('routes','line',4,'Les Carroz','{}','routes.rows.1.from'),
('routes','line',5,'Flaine','{}','routes.rows.1.to'),
('routes','line',6,'Green and blue','{}','routes.rows.1.grade'),
