('pass','note',0,'Sources: <a href="https://www.flaine.com/en/winter/skiing-snowsports/ski-passes/ski-passes.htm">the Flaine tourist office</a>, <a href="https://www.alti-mag.com/domaines-skiables/le-grand-massif">Alti-Mag</a> and <a href="https://www.alti-mag.com/domaines-skiables/villages-grand-massif">Alti-Mag for the Villages</a>.','{}','pass.table.note'),
