('pass','line',26,'The full pass at {{f:F000533}} for six days; the Flaine pass at {{f:F000699}} a day suits a short stay in the bowl.',array['F000533','F000699'],'pass.scenarios.0.what'),
('pass','line',27,'A week in Samoëns, Morillon or Les Carroz','{}','pass.scenarios.1.who'),
('pass','line',28,'The Villages pass at {{f:F000704}} covers {{f:F000656}} of piste; the full pass adds Flaine and the Cascades for {{diff:F000533,F000704}} more.',array['F000533','F000656','F000704'],'pass.scenarios.1.what'),
